  'brse-ik-008': {
    question: "Với tư cách là BrSE, vui lòng thiết kế cấu trúc trình bày khi đề xuất di chuyển sang nhóm công nghệ mới (ví dụ: React → Next.js, MySQL → PostgreSQL) cho khách hàng.",
    answer: "Trình bày đề xuất chuyển đổi công nghệ:\\n\\n1. Các vấn đề hiện tại (Tại sao):\\n- Những hạn chế và vấn đề cụ thể của nhóm công nghệ hiện tại\\n- Hiển thị bằng dữ liệu: vấn đề về hiệu suất, chi phí bảo trì tăng, lỗ hổng bảo mật\\n- Rủi ro \"như hiện tại\" (kết thúc hỗ trợ kỹ thuật, khó tuyển dụng nhân lực, v.v.)\\n\\n2. Công nghệ được đề xuất (Cái gì):\\n- Tổng quan về công nghệ mới (ngắn gọn và kèm theo các thuật ngữ kỹ thuật)\\n- Lịch sử áp dụng (các công ty/dự án nào đang sử dụng nó)\\n- Biểu đồ so sánh với các công nghệ hiện có (hiệu suất, khả năng bảo trì, chi phí học tập)\\n3. Kế hoạch di chuyển (Cách thức):\\n- Cách tiếp cận di chuyển theo từng giai đoạn (từng bước, không phải đột phá)\\n- Giai đoạn 1: Bằng chứng về khái niệm — Xác thực với chức năng nhỏ (2-4 tuần)\\n- Giai đoạn 2: Di chuyển thử nghiệm — Di chuyển một mô-đun (1-2 tháng)\\n- Giai đoạn 3: Di chuyển toàn diện — di chuyển phần còn lại theo từng giai đoạn\\n- Đảm bảo khoảng thời gian hoạt động song song\\n\\n4. Chi phí & Lợi nhuận:\\n- Chi phí di chuyển (giờ công, giấy phép, chi phí học tập)\\n- Hiệu quả mong đợi (cải thiện hiệu suất, giảm chi phí bảo trì, cải thiện hiệu quả phát triển)\\n- Ước tính ROI (giai đoạn phục hồi)\\n5. Rủi ro và biện pháp đối phó:\\n- Rủi ro công nghệ → Xác minh bằng PoC\\n- Rủi ro học tập nhóm → Đào tạo từng bước\\n- Rủi ro di chuyển thất bại → Kế hoạch khôi phục",
    explanation: "Điều khách hàng muốn nghe không phải là “chi tiết kỹ thuật” mà là “tại sao chúng tôi thay đổi, chi phí bao nhiêu và có rủi ro gì không?” Giá trị của BrSE là dịch những lời giải thích cho các kỹ sư sang ngôn ngữ kinh doanh và đưa ra đề xuất. Cách tiếp cận theo từng giai đoạn phù hợp với văn hóa \"không thích rủi ro\" của khách hàng Nhật Bản.",
  },
