  'brse-rs-007': {
    question: "Nếu có nhiều điểm không rõ ràng trong thông số kỹ thuật nhận được từ khách hàng Nhật Bản, vui lòng thiết kế quy trình Hỏi & Đáp (quản lý câu hỏi) dưới dạng BrSE.",
    answer: "Thiết kế quy trình hỏi đáp:\\n\\n1. Giai đoạn xem xét thông số kỹ thuật (1-2 ngày):\\n- BrSE + trưởng nhóm kỹ thuật + QA đọc kỹ thông số kỹ thuật\\n- Mỗi người ghi lại câu hỏi của mình vào bảng Hỏi đáp (Excel)\\n- Phân loại danh mục: Thông số kỹ thuật không xác định, mâu thuẫn, giả định chưa xác định, thiếu yêu cầu phi chức năng\\n2. Cấu trúc bảng hỏi đáp:\\n- Số | Danh mục | Phần liên quan (số trang/mục) | Nội dung câu hỏi | Đề xuất (Giải thích đề xuất của BrSE) | Trả lời | Bị đơn | Ngày | Trạng thái\\n- Cột \"Đề xuất\" rất quan trọng: Thay vì \"A hay B?\", hãy cho biết cách giải thích của bạn bằng cách nói \"Tôi hiểu rằng đó là A, nhưng nó có đúng không?\"\\n\\n3. Cuộc họp hỏi đáp (1-2 lần một tuần):\\n- Kiểm tra các câu hỏi theo thứ tự ưu tiên\\n- Giải quyết các câu hỏi quan trọng (ngăn cản sự bắt đầu phát triển) trước\\n- Đảm bảo ghi lại các câu trả lời trên bảng Hỏi đáp (không chỉ làm bằng lời nói)\\n\\n4. Phản hồi về câu trả lời:\\n- Tạo tài liệu bổ sung cho các thông số kỹ thuật dựa trên câu trả lời\\n- Chia sẻ với nhóm phát triển (phiên bản dịch của bảng Hỏi đáp)\\n- Sửa đổi ước tính/lịch trình nếu có tác động\\n\\n5. Quản lý chặt chẽ:\\n- Theo dõi các câu hỏi và trả lời chưa được trả lời hàng tuần\\n- Nâng cao nếu việc chờ đợi câu trả lời cản trở sự phát triển\\n- Đặt tất cả việc kết thúc câu hỏi và trả lời làm một cột mốc quan trọng",
    explanation: "Rủi ro lớn nhất là tiến hành mà không hiểu rõ các thông số kỹ thuật mơ hồ. Loại bỏ sự mơ hồ một cách có hệ thống bằng quy trình Hỏi & Đáp có cấu trúc. Bằng cách đưa ra một “đề xuất (cách giải thích của riêng họ), khách hàng có thể phản hồi bằng câu trả lời “có/không”, làm tăng hiệu quả phản hồi.",
  },
