    answer: "Mục NFR đa ngôn ngữ:\\n1. Mã ký tự: Hiển thị đa ngôn ngữ nhất quán bằng UTF-8. \\n2. Múi giờ: Quá trình chuyển đổi phù hợp với thời gian máy chủ, thời gian DB và thời gian hiển thị. \\n3. Tiền tệ/dấu thập phân: Thống nhất ký hiệu tiền tệ ở mỗi quốc gia và các quy tắc làm tròn như làm tròn. \\n4. Hiệu suất: Giảm thiểu độ trễ do tải tài nguyên đa ngôn ngữ (tệp i18n). \\n5. Khả năng tìm kiếm: Khả năng đáp ứng các tìm kiếm mơ hồ của tiếng Nhật (hiragana, katakana, kanji).",
