    "Vận hành triệt để Wiki (tài liệu) trong dự án, giới thiệu văn hóa đánh giá mã và lập trình cặp, đồng thời xây dựng một hệ thống (tiêu chuẩn hóa) trong đó bí quyết được phân phối và chia sẻ trong toàn nhóm.",
